int gcd(int a, int b)
{
    // Euclid: gcd(a, b) == gcd(b, a % b), and gcd(a, 0) == a
    while (b != 0)
    {
        const int r{ a % b };
        a = b;
        b = r;
    }
    return a < 0 ? -a : a;
}

